  "civic.data.city_supply.description": "Unlocks the “City Supply” Policy Card: increases the population cap by {populationCapIncrease}, reduces population growth time by {populationGrowthTimeReductionPercent}%, and replaces “Town Meeting.”",
  "civic.data.city_supply.inspiration": "Inspiration: Reach level {buildingLevel} in the Low-Rent Community.",
  "civic.data.city_supply.name": "City Supply",
