  "civic.data.mercantilism.inspiration": "Inspiration: Have {merchantCount} Merchants at once.",
  "civic.data.mercantilism.name": "Mercantilism",
  "civic.data.mineral_charter.description": "Unlocks the “Mineral Charter” Policy Card: Iron output +{ironOutputBonusPercent}%.",
  "civic.data.mineral_charter.inspiration": "Inspiration: Produce {ironGatherThreshold} Iron in total.",
