  "civic.data.prehistoric_civics.name": "Prehistoric Civics",
  "civic.data.prosperity_and_unity.description": "Unlocks the “Supreme Way” Policy Card (alien building output +{alienBuildingOutputBonusPercent}%) and the “Federal Privy Council” Policy Card (multiplies Officials’ Civic Point output in the Plaza and Opera House by {officialCivicPointMultiplier}, replacing “Political Economy”).",
  "civic.data.prosperity_and_unity.inspiration": "Prerequisite: Distributed Sovereignty. Inspiration: Adopt the Interstellar Federation government.",
  "civic.data.prosperity_and_unity.name": "Prosperity and Unity",
  "civic.data.protect_the_planet.description": "Unlocks the “Protect the Planet” Policy Card (removes {pollutionReductionPerMerfolkPerSecond} Pollution per second for each Merfolk) and the Nature Reserve building (removes {pollutionReductionPerReservePerSecond} Pollution per second each).",
  "civic.data.protect_the_planet.inspiration": "Inspiration: Reach {pollutionStockThreshold} stored Pollution (Dead Zone).",
  "civic.data.protect_the_planet.name": "Protect the Planet",
  "civic.data.public_cemetery.description": "Unlocks the Graveyard building ({restingPlacesPerCemetery} resting places each) and the “Sacrament of Confession” Policy Card (each Temple adds {restingPlacesPerTemple} more resting place).",
  "civic.data.public_cemetery.inspiration": "Inspiration: Have a Merfolk die from Pollution.",
  "civic.data.public_cemetery.name": "Public Graveyard",
  "civic.data.public_health.description": "Unlocks the Hospital building: each level reduces the probability of death from Pollution, with diminishing returns, up to {maximumPollutionDeathProbabilityReductionPercent}% at level {hospitalLevelCap}.",
  "civic.data.public_health.inspiration": "Inspiration: Reach {pollutionStockThreshold} stored Pollution (Red Tide).",
  "civic.data.public_health.name": "Public Health",
  "civic.data.public_works.description": "Unlocks the Terra and Enceladus Orbital Launch Sites. They use the same launch cycle and material costs as the Europa Launch Site, with construction costs starting at level {baseBuildingLevel} and no level discount from Planetary Terraforming.",
  "civic.data.public_works.inspiration": "Prerequisite: Solar System Logistics. Inspiration: Reach level {buildingLevel} in the Europa Launch Site.",
  "civic.data.public_works.name": "Public Works Agency",
