  "civic.data.reformation.name": "Reformation",
  "civic.data.sacred_path.description": "Unlocks “Mind Over Matter” (Wonder construction costs −{wonderConstructionCostReductionPercent}%) and “Transcendence” (Research Points +{researchPointsPerSecond}/s, replacing “Mysticism”).",
  "civic.data.sacred_path.inspiration": "Prerequisite: Faith in the Stars. Inspiration: Adopt the Universal Church government.",
  "civic.data.sacred_path.name": "Sacred Path",
  "civic.data.sanitation_act.description": "Unlocks the “Quarantine” Policy Card: reduces the chance of death from Pollution by {pollutionDeathProbabilityReductionPercent}%, unaffected by the Hospital soft cap.",
  "civic.data.sanitation_act.inspiration": "Inspiration: Reach {pollutionStockThreshold} stored Pollution.",
  "civic.data.sanitation_act.name": "Sanitation Act",
  "civic.data.social_network.description": "Unlocks the “Social Network” Policy Card, replacing “Mass Media.”",
