  "civic.data.social_science.name": "Social Science",
  "civic.data.solar_system_logistics.description": "Unlocks “Interstellar Logistics Support” (Rocket Engine and Strong Propellant Rocket Engine crafting efficiency +{rocketCraftingEfficiencyBonusPercent}%) and “Brilliant Star Map” (population Faith output −{populationFaithOutputReductionPercent}%, Research Point production ×{researchOutputMultiplier}; replaces “No God Here”).",
  "civic.data.solar_system_logistics.inspiration": "Prerequisite: Prosperity and Unity, Common Destiny, or Sacred Path. Inspiration: Complete the “Interplanetary Rapid Logistics” technology.",
  "civic.data.solar_system_logistics.name": "Solar System Logistics",
  "civic.data.songs_of_the_deep.description": "Unlocks the Cha’Dosan Grand Theatre Wonder (+{civicPointsPerSecond} Civic Points/s and +{policySlotCount} Policy Card slot) and the Opera House building.",
  "civic.data.songs_of_the_deep.inspiration": "Inspiration: Reach {zoneBuildingLevels} total building levels in the Civic zone.",
  "civic.data.songs_of_the_deep.name": "Songs of the Deep",
  "civic.data.space_race.description": "Unlocks the “Space Race” and “No God Here” Policy Cards and the Bolosillo Floating Launch Site Wonder.",
