  "civic.data.star_ruins.description": "At Shellbreak settlement this Prestige cycle, each level of an orbital or alien facility increases Stardust gains by {stardustBonusPerFacilityLevelPercent}%.",
  "civic.data.star_ruins.inspiration": "Inspiration: Accumulate more than {totalStardustThreshold} Stardust across all Prestige cycles.",
  "civic.data.star_ruins.name": "Interstellar Ruins",
