  "game.story.unlock.civics.action": "Go to Civics",
  "game.story.unlock.civics.line_1": "For the first time, the merfolk gathered around the same stone table.",
  "game.story.unlock.civics.line_2": "They pooled food, assigned work, and settled disagreements. Civilization began here.",
  "game.story.unlock.civics.system_description": "You can now research Civics, choose a Government, and equip Policy Cards.",
  "game.story.unlock.civics.system_title": "The Civics system is now available",
  "game.story.unlock.civics.title": "Civics unlocked",
  "game.story.unlock.company.action": "Go to Companies",
  "game.story.unlock.company.line_1": "We eat biosynthesized fish roe and lab-grown kelp—damn it, even photosynthesis has a patent!",
  "game.story.unlock.company.system_description": "Kelp and Coral companies now form automatically and grow over time, boosting their respective resource output.",
  "game.story.unlock.company.system_title": "The Company system is now available",
  "game.story.unlock.company.title": "Companies unlocked",
  "game.story.unlock.faith.action": "Go to Faith",
  "game.story.unlock.faith.line_1": "A priest etched the tides, the people, and the glow of deep-sea fire onto one thin stone tablet.",
  "game.story.unlock.faith.line_2": "But why did every priest understand it differently?",
  "game.story.unlock.faith.system_description": "You can view Faith production and global bonuses, and give your religion a name.",
  "game.story.unlock.faith.system_title": "The Faith system is now available",
  "game.story.unlock.faith.title": "Faith unlocked",
  "game.story.unlock.prestige.action": "Got it",
  "game.story.unlock.prestige.line_1": "The merfolk’s hymns rode the deep currents, reaching every corner of the kingdom.",
  "game.story.unlock.prestige.line_2": "The priests saw the warming currents and tides as a mirror of civilization’s own cycle…",
  "game.story.unlock.prestige.line_3": "From now on, ending a run begins a new Prestige. Spend Prestige Points in the Prestige Shop for permanent bonuses.",
  "game.story.unlock.prestige.title": "Prestige unlocked",
  "game.story.unlock.star_map.action": "Go to Star Map",
  "game.story.unlock.star_map.line_1": "Countless ages had passed since the merfolk first looked up at the Shell overhead.",
  "game.story.unlock.star_map.line_2": "Today, for the first time, they saw stars glittering beyond the ice.",
  "game.story.unlock.star_map.system_description": "You can now explore Europa and Saturn, along with any Satellites or Space Stations launched during this run.",
  "game.story.unlock.star_map.system_title": "The Star Map is now open",
  "game.story.unlock.star_map.title": "Star Map unlocked",
  "game.story.unlock.technology.action": "Go to Technology",
  "game.story.unlock.technology.line_1": "The merfolk tied a small, tough piece of deep-sea kelp into a knot. “This stands for today,” he said.",
  "game.story.unlock.technology.line_2": "Then he tied a second knot. “This stands for tomorrow.”",
  "game.story.unlock.technology.title": "Technology unlocked",
  "game.story.unlock.wonder.action": "Go to Wonders",
  "game.story.unlock.wonder.line_1": "More than a dozen stonemasons spread blueprints across a stone table. The final design stretched beyond the whole habitat.",
  "game.story.unlock.wonder.system_description": "You can now view and build unique Wonders. They remain after each Prestige and grant bonuses.",
  "game.story.unlock.wonder.system_title": "Wonder blueprints revealed",
  "game.story.unlock.wonder.title": "Wonders unlocked",
  "game.story.unlock.workshop.action": "Go to Workshop",
  "game.story.unlock.workshop.line_1": "An anvil, a hammer, rope, and artisans who know their craft.",
  "game.story.unlock.workshop.line_2": "If a tool can repeat yesterday’s work for us, could it also help us create something new?",
  "game.story.unlock.workshop.system_description": "You can now craft items, buy profession tools, and install permanent upgrades.",
  "game.story.unlock.workshop.system_title": "Crafting is now available",
  "game.story.unlock.workshop.title": "Workshop unlocked",
