  "tech.coralcut.name": "Coral Carving",
  "tech.coralcut.note": "Unlocks the Coralworker. Coral for the first Reef Nest must be gathered by hand; once you have enough, you can free a person to take up the job.",
  "tech.crewed.name": "Crewed Spaceflight",
  "tech.crewed.unlock_desc": "Unlocks the Rocket Engine recipe and Controlled Detonation Crafting Workshop upgrade, which multiplies crafting efficiency by {craftingMultiplier}.",
  "tech.deepspace.name": "Deep-Space Mechanics",
  "tech.deepspace.unlock_desc": "Unlocks the Voyager 1 wonder. While Star Exploration is below {thresholdPercent}, it adds {earlyExplorationRate} Star Exploration/sec. At or above {thresholdPercent}, it adds {lateExplorationRate}/sec and increases Scholar output by {scholarBonus}.",
  "tech.drift_tech.name": "Wandering Terra",
  "tech.drift_tech.unlock_desc": "Unlocks the Planetary Engine in the Beyond-the-Shell Zone.",
  "tech.ecological_restoration.name": "Ecological Reshaping",
  "tech.ecological_restoration.unlock_desc": "Unlocks the G.E.E.K. Planetary Terraformer wonder. After terraforming Enceladus, upgrade costs for People, Fast-Growing Coral Groves, Mines, and Habitat Zone buildings reset to their pre-level-{levelThreshold} costs.",
  "tech.education.name": "Education",
  "tech.education.unlock_desc": "Unlocks the University Research Institute upgrade, which increases Scholar Research Point output by {perLevelPercent} per level, and the Albada Hydrothermal University wonder.",
  "tech.effect.additive": "{effectName} +{amount}",
